#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=9

# Run from the app folder whatever the caller's directory; values go to .env.local.
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
ENV_FILE=".env.local"

# ask_until KEY "Prompt" REGEX "hint": ask (visible) until the value matches.
ask_until() {
  local key="$1" prompt="$2" pattern="$3" hint="$4"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

# ask_secret_until KEY "Prompt" REGEX "hint": hidden input until it matches.
ask_secret_until() {
  local key="$1" prompt="$2" pattern="$3" hint="$4"
  while true; do
    ask_secret "$key" "$prompt"
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

E164='^\+[1-9][0-9]{7,14}$'

# Keep the simulated-demo settings once, before this wizard changes them.
if [[ -f "$ENV_FILE" && ! -f .env.simulator ]]; then
  cp "$ENV_FILE" .env.simulator
fi

banner "Lightline: real phone test (Twilio + ElevenLabs)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Twilio: log in"
say "Twilio owns the phone numbers. The account must be UPGRADED (pay as you go):"
say "Twilio trials strip ringing Amy, the AI audio stream and voicemail from every call."
note "Done on 2026-10-28: account upgraded, business profile approved. Nothing to sign up for."
open_url "https://console.twilio.com/"
step "Log in to the business's Twilio account."
note "Typical test spend: about 1 cent a minute; the number is \$1.15 a month."
pause "Press Enter when you're on the Console home page."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Twilio: the Christmas Light Guys number"
say "A number just for Christmas lights: the new Christmas site, the TV ad and the QR code."
say "512-339-9313 stays on Amy's own system for every company (Amy, 2026-10-28: don't touch it)."
note "Already bought on 2026-10-28: +17373398333 (Twilio had no 512 numbers left)."
open_url "https://console.twilio.com/us1/develop/phone-numbers/manage/incoming"
step "Check it's listed under Phone Numbers. Buying another is only needed if it isn't."
ask_until CLG_MAIN_NUMBER "The Christmas Light Guys number (+1XXXXXXXXXX):" "$E164" "Use the +1XXXXXXXXXX form, no spaces or dashes."
write_env CLG_MAIN_NUMBER "$CLG_MAIN_NUMBER"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Optional: Bestline forwarding, or the other companies"
say "Not needed now. Skip everything here with Enter."
say "Only if 512-339-9313 should ever forward to us, or Sublime Patio / The Fridge get numbers too."
for key in SHARED_LINE_NUMBER BESTLINE_MISSED_NUMBER SUBLIME_PATIO_NUMBER THE_FRIDGE_NUMBER; do
  case "$key" in
    SHARED_LINE_NUMBER) label="Bestline forward-all target (rings Amy first, asks which company)" ;;
    BESTLINE_MISSED_NUMBER) label="Bestline no-answer target (assistant answers at once)" ;;
    SUBLIME_PATIO_NUMBER) label="Sublime Patio" ;;
    THE_FRIDGE_NUMBER) label="The Fridge" ;;
  esac
  while true; do
    ask "$key" "${label} (+1XXXXXXXXXX, or Enter to skip):"
    [[ -z "${!key}" || "${!key}" =~ $E164 ]] && break
    warn "Use the +1XXXXXXXXXX form, or leave it empty."
  done
  write_env "$key" "${!key}"
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Twilio: account keys"
say "The app uses these to check Twilio's signatures and to move live calls."
open_url "https://console.twilio.com/"
step "On the Console home, find \"Account Info\" (scroll down if needed)."
step "Copy the Account SID (starts with AC)."
ask_until TWILIO_ACCOUNT_SID "Paste the Account SID:" '^AC[0-9a-fA-F]{32}$' "An Account SID is AC followed by 32 letters/digits."
step "Click \"Show\" (or the copy icon) next to Auth Token, and copy it."
ask_secret_until TWILIO_AUTH_TOKEN "Paste the Auth Token (hidden):" '^[0-9a-fA-F]{32}$' "An Auth Token is 32 letters/digits. Paste it again."
write_env TWILIO_ACCOUNT_SID "$TWILIO_ACCOUNT_SID"
write_env TWILIO_AUTH_TOKEN "$TWILIO_AUTH_TOKEN"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Who answers first?"
say "Two ways a call can go, Mon–Sat 9–5 Austin time:"
say "  Ring first: Amy's phone rings; she presses any key to take it, else the assistant answers."
say "  Assistant first: the assistant answers; Amy's phone rings only when a caller asks for her."
say "Nights and Sundays the assistant always answers. Either way, every call becomes a lead for Amy."
printf '\n'
if confirm "Is there a phone to play Amy (Amy's cell, or a test phone)?"; then
  note "For the real setup this is Amy's own cell. For a test: a phone OTHER than the one you call from."
  ask_until OWNER_RING_E164 "That phone (+1XXXXXXXXXX):" "$E164" "Use the international + form, digits only."
  write_env OWNER_RING_E164 "$OWNER_RING_E164"
  if confirm "Should that phone ring first (the plan for Amy)?"; then
    write_env AI_MODE "overflow"
    note "That phone rings first Mon–Sat 9–5 (press any key to take it); otherwise the assistant answers."
  else
    write_env AI_MODE "always"
    note "The assistant answers first; that phone rings only when a caller asks for Amy, Mon–Sat 9–5."
  fi
else
  write_env AI_MODE "always"
  note "The assistant answers every call; it can't put anyone through until a phone is added (re-run this)."
fi
write_env RING_START "09:00"
write_env RING_END "17:00"
write_env RING_DAYS "1,2,3,4,5,6"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Safety net: if this app is ever down"
say "If our app can't answer, Twilio can run a tiny backup script it hosts itself."
say "It rings Amy's cell, and if she doesn't answer, takes a message. Like today, without the assistant."
amy_for_bin="${OWNER_RING_E164:-$(_existing OWNER_RING_E164 || true)}"
if [[ -z "$amy_for_bin" ]]; then
  ask_until amy_for_bin "Amy's cell for the backup (+1XXXXXXXXXX):" "$E164" "Use the +1XXXXXXXXXX form."
fi
open_url "https://console.twilio.com/us1/develop/twiml-bins/twiml-bins"
step "Create a new TwiML Bin (Console → search \"TwiML Bins\" if the page moved). Name it: lightline-backup."
step "Paste exactly this as its TwiML, then Save:"
printf '\n%s\n\n' "<Response><Dial timeout=\"25\"><Number>${amy_for_bin}</Number></Dial><Say>Thanks for calling. Amy can't get to the phone right now. After the tone, please say your name, which company you're calling about, what you need, and the best time to reach you.</Say><Record maxLength=\"120\" playBeep=\"true\"/></Response>"
step "Copy the Bin's URL (starts with https://handler.twilio.com/twiml/)."
note "Exact menu names may differ slightly in Twilio's console."
while true; do
  ask TWILIO_FALLBACK_URL "Bin URL (or Enter to skip):"
  [[ -z "$TWILIO_FALLBACK_URL" || "$TWILIO_FALLBACK_URL" =~ ^https://handler\.twilio\.com/twiml/ ]] && break
  warn "It should start with https://handler.twilio.com/twiml/"
done
write_env TWILIO_FALLBACK_URL "$TWILIO_FALLBACK_URL"
[[ -n "$TWILIO_FALLBACK_URL" ]] || SKIPPED+=("TwiML Bin backup (TWILIO_FALLBACK_URL): without it, forwarded callers hear an error if the app is down")

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "ElevenLabs: API key"
say "ElevenLabs is the voice (ears and mouth). The setup script builds the agent for you."
note "Done on 2026-10-28: Creator plan, restricted key (ElevenAgents write, Voices read, Webhooks)."
open_url "https://elevenlabs.io/app/settings/api-keys"
step "Paste the key you created and saved. It is shown only once:"
step "if it's lost, delete it there and create a new one with the same three permissions."
ask_secret_until ELEVENLABS_API_KEY "Paste the API key (hidden):" '^sk_[A-Za-z0-9]{20,}$' "ElevenLabs keys start with sk_. Paste it again."
write_env ELEVENLABS_API_KEY "$ELEVENLABS_API_KEY"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Public tunnel (cloudflared)"
say "Twilio and ElevenLabs must reach this PC. cloudflared gives it a temporary https address."
cloudflared_path=""
for candidate in "$(command -v cloudflared 2>/dev/null || true)" \
                 "/c/Program Files (x86)/cloudflared/cloudflared.exe" \
                 "/c/Program Files/cloudflared/cloudflared.exe" \
                 "${LOCALAPPDATA:-}/Microsoft/WinGet/Links/cloudflared.exe"; do
  if [[ -n "$candidate" && -f "$candidate" ]]; then cloudflared_path="$candidate"; break; fi
done
if [[ -n "$cloudflared_path" ]]; then
  note "cloudflared is installed: $cloudflared_path"
elif command -v winget >/dev/null 2>&1 && confirm "Install Cloudflare's cloudflared with winget now (about 20 MB, from Cloudflare)?"; then
  winget install --id Cloudflare.cloudflared -e || warn "winget did not finish; install cloudflared and re-run."
  note "If 'npm run live' can't find it, open a new terminal so PATH refreshes."
else
  SKIPPED+=("Install cloudflared (winget install --id Cloudflare.cloudflared -e), or run: npm run live -- --url https://your-tunnel")
  warn "Skipped. You can pass your own https tunnel to npm run live with --url."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Save live settings"
write_env AGENT_PROVIDER "elevenlabs"
write_env OWNER_NAME "Amy"
write_env ALERT_MODE "simulate"
write_env PGLITE_DIR ".data/live"
# Live answers come only from Amy's decisions (her 2026-10-22 email and /approvals), never demo approvals.
write_env DEMO_APPROVED_KEYS ""
write_env AMY_DECISIONS "on"
note "The assistant uses Amy's answers from her email; nothing is approved for demo."
note "Alerts stay simulated (no texts yet): texting Amy needs Twilio's A2P 10DLC registration first."
note "Your simulated-demo settings are saved in .env.simulator."
note "npm run live creates the tool key, agent, webhook and tunnel URL itself."
say ""
say "Next, in this folder run:"
say "  ${BOLD}npm run live -- --fresh${RESET}"
say "Then call the Christmas Light Guys number from your mobile to test."

finish
